from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'dist'
ITEMS = [('index.html','Fluid Planner'),('potassium.html','Potassium'),('magnesium.html','Magnesium'),('phosphate.html','Phosphate'),('sodium.html','Sodium'),('dextrose.html','Dextrose'),('blood-collection.html','Blood Collection'),('drugs.html', 'Drugs'), ('sources.html','Sources & Workbook Map')]

def number(id, label, unit, value='', minimum='0', required=True):
    return f'<label>{label} <span>{unit}</span><input id="{id}" type="number" min="{minimum}" step="any" value="{value}" {"required" if required else ""}></label>'

def stock(group, entries, note):
    fields=''.join(number(i,l,u,v,m).replace('type="number"','data-stock type="number" readonly') for i,l,u,v,m in entries)
    ids=','.join(e[0] for e in entries)
    return f'<details class="stock-settings"><summary>Stock concentrations — locked by default</summary><div class="grid">{fields}</div><button type="button" data-lock="{ids}">Edit concentrations</button><span class="lock-state" data-lock-state="{ids}">Locked</span><p class="help">{note}</p></details>'

def results(id):
    return f'<section class="panel results" id="{id}Section" tabindex="-1"><h2>Selected preparation & math</h2><div id="{id}" aria-live="polite"></div><details id="{id}Math" class="worked-math"><summary>Show worked math</summary><ol id="{id}Steps"></ol></details></section>'

def shell(filename,title,intro,body,tool):
    links=''.join(f'<a href="{file}"'+(' aria-current="page"' if file==filename else '')+f'>{label}'+('<span class="current-page">Current</span>' if file==filename else '')+'</a>' for file,label in ITEMS)
    group_helpers={'__file__':str(Path(__file__).resolve().parent/'group-navigation.py')}
    exec((Path(__file__).resolve().parent/'group-navigation.py').read_text().split("if __name__")[0],group_helpers)
    links=group_helpers['group_links'](links,filename)
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · ER Reference</title><link rel="stylesheet" href="style.css"></head><body class="potassium-page" data-tool="{tool}"><header><a class="brand" href="index.html">ER<span>REFERENCE</span></a><span class="edition">DEVELOPMENT DRAFT · 07</span></header><a class="skip-link" href="#main-content">Skip to content</a><aside class="sidebar" aria-label="Reference navigation"><details id="sectionMenu" open><summary>Sections <span>— {title}</span></summary><div class="sidebar-title">REFERENCE TOOLS</div><nav aria-label="Reference sections">{links}</nav></details></aside><main id="main-content"><div class="eyebrow">FLUIDS / {title.upper()}</div><h1>{title}</h1><p class="intro">{intro}</p>{body}<footer>Fluids-tab implementation · Sources reviewed October 17, 2026 · Independent clinical and browser validation pending. <a href="sources.html">Sources & workbook map</a>.</footer></main><script src="electrolyte-calc.js"></script><script src="electrolytes.js"></script><script src="navigation.js"></script></body></html>'''
    (ROOT/filename).write_text(html)

mg_inputs=number('mWeight','Weight','kg',minimum='.001')+number('mHours','Preparation duration','hours','24','.001')+number('mVolume','Final diluted infusion volume','mL',minimum='.001')
mg_stock=stock('m',[('mStock','MgSO₄ stock','mEq/mL','4','.001')],'Workbook default: 4 mEq/mL. Some 50% labels specify 4.06 mEq/mL; verify the vial and edit deliberately if needed. Stock volume must be diluted, not administered undiluted.')
mg_rows=''.join(f'<tr><th scope="row">{label}</th><td><button class="lyte-rate" type="button" data-target="mDose" data-value="{dose}" data-result="mResult">Use {dose}</button></td><td id="mAmount{i}">—</td><td id="mMl{i}">— mL</td></tr>' for i,(label,dose) in enumerate([('Low extracellular Mg — workbook option',1),('Normal Mg with refractory K — workbook option',.5)]))
shell('magnesium.html','Magnesium','Daily dosing stays daily: a shorter preparation contains a proportional fraction of the daily amount.',f'''<div class="notice">These are the workbook’s two dose options, not an automatic serum-Mg treatment rule. Assess indication, renal function, dilution, and monitoring separately. <a href="sources.html#magnesium-source">Evidence and limits</a>.</div><form data-electrolyte><section class="panel"><h2>1. Patient & preparation</h2><div class="patient-grid">{mg_inputs}</div>{mg_stock}</section><section class="panel dose-reference live-reference"><h2>2. Compare daily dose options</h2><p class="help">Dose units are mEq/kg/day. The table shows the amount for the entered hours, not a whole daily dose compressed into that time.</p><div class="table-wrap"><table><thead><tr><th>Workbook context</th><th>Daily dose<br>mEq/kg/day</th><th class="meq-column">Amount for entered hours<br>mEq</th><th class="ml-column">MgSO₄ VOLUME TO ADD<br>mL stock</th></tr></thead><tbody>{mg_rows}</tbody></table></div>{number('mDose','Selected / custom daily dose','mEq/kg/day')}<button type="reset">Clear inputs & restore stock</button></section></form>{results('mResult')}''','magnesium')

p_inputs=number('pWeight','Weight','kg',minimum='.001')+number('pRate','Fluid rate','mL/hr',minimum='.001')+number('pVolume','Preparation volume','mL',minimum='.001')
p_stock=stock('p',[('pStock','Phosphate stock','mmol/mL','3','.001'),('pKStock','Potassium in the same stock','mEq/mL','4.4','0')],'Both concentrations describe the same KPhos product. Verify both on its label. Editable potassium concentration is used in every calculation; no hardcoded 4.4 in the math.')
p_rows=''
for i,(label,rates) in enumerate([('2–2.7 mg/dL',[.01,.02]),('1–2 mg/dL',[.03,.06]),('&lt;1 mg/dL',[.06,.12])]):
    buttons=''.join(f'<button type="button" class="lyte-rate" data-target="pDose" data-value="{rate}" data-result="pResult">{"Lower" if j==0 else "Upper"} {rate}</button>' for j,rate in enumerate(rates))
    p_rows+=f'<tr><th scope="row">{label}</th><td><div class="rate-options">{buttons}</div></td><td id="pK{i}">—</td><td id="pMl{i}">— mL</td></tr>'
shell('phosphate.html','Phosphate','Live KPhos preparation with its potassium contribution shown explicitly.',f'''<div class="notice"><b>Use a compatible calcium-free carrier. Do not mix phosphate with LRS or calcium-containing solutions.</b> Dose bands match the workbook and the cited VetEmCrit author guidance. Choose a dose using the patient’s current phosphorus and clinical context. <a href="sources.html#phosphate-source">Sources</a>.</div><form data-electrolyte><section class="panel"><h2>1. Patient & fluid</h2><div class="patient-grid">{p_inputs}</div><div class="grid"><label>Preparation method<select id="pMethod"><option value="final">Specified final volume — replace equal carrier volume</option><option value="add">Existing carrier volume — add stock on top</option></select></label>{number('pOtherK','Supplemental K from separate infusions','mEq/kg/hr','0')}</div>{p_stock}<p class="help">Carrier potassium is excluded, as on the KCl page. Other K means separate infusions, not KCl mixed into this same bag.</p></section><section class="panel dose-reference live-reference"><h2>2. Choose the phosphate rate</h2><div class="table-wrap"><table><thead><tr><th>Current phosphorus</th><th>Phosphate rate<br>mmol/kg/hr</th><th class="meq-column">K from KPhos<br>mEq/kg/hr</th><th class="ml-column">KPHOS VOLUME TO ADD<br>mL stock</th></tr></thead><tbody>{p_rows}</tbody></table></div><p class="help">The source bands meet at 2 mg/dL; choose in clinical context. No automatic band assignment. Combined entered supplemental K must not exceed this tool’s 0.5 mEq/kg/hr limit.</p>{number('pDose','Selected / custom phosphate rate','mmol/kg/hr')}<button type="reset">Clear inputs & restore stocks</button></section></form>{results('pResult')}''','phosphate')

d_stock=stock('d',[('dStock','Dextrose stock','%','50','.001'),('dBase','Dextrose already in carrier','%','0','0')],'Defaults reproduce the workbook: 50% stock and dextrose-free carrier. This tool prepares a specified final volume; remove carrier volume equal to stock added.')
d_rows=''.join(f'<tr><th scope="row">{target}%</th><td><button type="button" class="lyte-rate" data-target="dTarget" data-value="{target}" data-result="dResult">Use {target}%</button></td><td id="dCarrier{i}">— mL</td><td id="dMl{i}">— mL</td></tr>' for i,target in enumerate([1.25,2.5,5]))
shell('dextrose.html','Dextrose','Prepare a final dextrose concentration with the stock volume clearly emphasized.',f'''<div class="notice">This is a fluid-mixing calculator, not a hypoglycemia bolus protocol. Select concentration and access for the patient; concentrations above 5% warrant central-line consideration per AAHA. <a href="sources.html#dextrose-source">Source</a>.</div><form data-electrolyte><section class="panel"><h2>1. Final prepared volume</h2>{number('dVolume','Final prepared volume','mL',minimum='.001')}{d_stock}</section><section class="panel dose-reference live-reference"><h2>2. Choose the final concentration</h2><div class="table-wrap"><table><thead><tr><th>Final concentration</th><th>Select</th><th class="meq-column">Carrier volume<br>mL</th><th class="ml-column">DEXTROSE VOLUME TO ADD<br>mL stock</th></tr></thead><tbody>{d_rows}</tbody></table></div>{number('dTarget','Selected / custom final concentration','%')}<button type="reset">Clear inputs & restore stocks</button></section></form>{results('dResult')}''','dextrose')

water=f'''<form data-electrolyte><section class="panel"><h2>Free-water deficit — hypernatremia</h2><p class="help">Enter a clinician-selected patient sodium target. This estimates free-water replacement only, not the complete fluid prescription.</p><div class="patient-grid">{number('nWeight','Weight','kg',minimum='.001')}{number('nCurrent','Current patient Na','mEq/L',minimum='.001')}{number('nGoal','Patient Na target','mEq/L',minimum='.001')}</div><div class="grid"><label>Hypernatremia context<select id="nType"><option value="chronic">Chronic / uncertain duration — 0.5 mEq/L/hr reference</option><option value="acute">Confirmed acute — 1 mEq/L/hr time estimate</option></select></label>{number('nHours','Custom replacement duration (optional)','hours',minimum='.001',required=False)}</div><p class="help">Blank duration uses the context’s reference estimate. Total-body-water fraction is 0.6, matching the workbook. Changing the target changes the estimate.</p><button type="reset">Clear free-water inputs</button></section></form>{results('nWater')}'''
n_stock=stock('n',[('nBase','Carrier Na','mEq/L','130','0'),('nStock','Stock / replacement Na','mEq/L','1232','0')],'Workbook defaults: LRS 130 mEq/L and 7.2% NaCl 1232 mEq/L. Verify the actual product label. D5W is sodium-free; select its preset to lower fluid Na.')
mix=f'''<form data-electrolyte><section class="panel"><h2>Fluid sodium mixing — specified final volume</h2><p><b>The target here is the fluid’s sodium concentration, not the patient’s sodium.</b> This does not predict the patient’s sodium change.</p><div class="grid">{number('nVolume','Final fluid volume','mL',minimum='.001')}{number('nFluidGoal','Target fluid Na','mEq/L')}</div><label>Stock / replacement preset<select id="nPreset"><option value="1232">7.2% NaCl — workbook 1232 mEq/L</option><option value="0">D5W — 0 mEq/L</option><option value="custom">Custom — deliberately edit below</option></select></label>{n_stock}<button type="reset">Clear mixing inputs & restore stocks</button></section></form>{results('nMix')}'''
quick=f'''<form data-electrolyte><section class="panel"><h2>Mixing quick math — calculate final sodium</h2><p class="help">Replaces the spreadsheet’s manually entered quick-math sodium results with a calculation.</p><div class="grid">{number('qVolumeA','Fluid A volume','mL')}{number('qNaA','Fluid A Na','mEq/L','130')}{number('qVolumeB','Fluid B volume','mL')}{number('qNaB','Fluid B Na','mEq/L','0')}</div><button type="reset">Clear quick math</button></section></form>{results('nQuick')}'''
glucose=f'''<form data-electrolyte><section class="panel"><h2>Glucose-corrected sodium</h2><p class="help">Workbook equation, with a 1.6 correction factor supported by a 2024 canine hyperglycemic-crisis study. Feline use is extrapolation; select species explicitly.</p><div class="patient-grid">{number('gNa','Measured sodium','mEq/L',minimum='.001')}{number('gGlucose','Blood glucose','mg/dL',minimum='100')}<label>Species<select id="gSpecies"><option value="dog">Canine</option><option value="cat">Feline — extrapolated equation</option></select></label></div><button type="reset">Clear glucose correction</button></section></form>{results('nGlucose')}'''
shell('sodium.html','Sodium','Keep patient correction planning separate from fluid formulation.',f'''<div class="notice">Chronic sodium disturbances require controlled correction and serial reassessment. The chronic hypernatremia tool enforces ≤0.5 mEq/L/hr; the reference daily ceiling is 10–12 mEq/L/day. Free water does not replace resuscitation for hypovolemia. <a href="sources.html#sodium-source">Sources and limits</a>.</div><nav class="local-tools" aria-label="Sodium calculators"><a href="#nWaterSection">Free water</a><a href="#nMixSection">Fluid mixing</a><a href="#nQuickSection">Quick math</a><a href="#nGlucoseSection">Glucose correction</a></nav>{water}{mix}{quick}{glucose}''','sodium')

# Apply the expanded shared sidebar to existing pages without touching their calculators.
for filename in ['index.html','potassium.html','sources.html']:
    p=ROOT/filename;s=p.read_text();start=s.index('<nav aria-label="Reference sections">');end=s.index('</nav>',start)+len('</nav>')
    links=''.join(f'<a href="{file}"'+(' aria-current="page"' if file==filename else '')+f'>{label}'+('<span class="current-page">Current</span>' if file==filename else '')+'</a>' for file,label in ITEMS)
    group_helpers={'__file__':str(Path(__file__).resolve().parent/'group-navigation.py')}
    exec((Path(__file__).resolve().parent/'group-navigation.py').read_text().split("if __name__")[0],group_helpers)
    links=group_helpers['group_links'](links,filename)
    s=s[:start]+'<nav aria-label="Reference sections">'+links+'</nav>'+s[end:];p.write_text(s)

# Keep generated pages aligned with the clinical-workflow refinements.
import subprocess
import sys
subprocess.run([sys.executable, str(ROOT.parent/"scripts/refine-electrolytes.py")], check=True)
